import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Trash2 } from 'lucide-react';
import FileUpload from './components/FileUpload';
import ProductUpload from './components/ProductUpload';
import KPIHeader from './components/KPIHeader';
import ConsolidationAlerts from './components/ConsolidationAlerts';
import OrdersTable from './components/OrdersTable';
import AnalyticsChart from './components/AnalyticsChart';
import './App.css';

function App() {
  const [orders, setOrders] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchLatestOrders = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:5000/api/orders/latest');
      setOrders(response.data.orders || []);
      setAlerts(response.data.alerts || []);
    } catch (error) {
      console.error('Error fetching orders:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLatestOrders();
  }, []);

  const handleUploadSuccess = (data) => {
    setOrders(data.orders);
    setAlerts(data.alerts);
  };

  const handleUpdateActualTrucks = async (id, actualTrucks) => {
    try {
      await axios.patch(`http://localhost:5000/api/orders/${id}/actual`, { actualTrucks });
      fetchLatestOrders();
    } catch (error) {
      console.error('Error updating actual trucks:', error);
    }
  };

  const handleDeleteLatest = async () => {
    if (window.confirm('Are you sure you want to delete the latest uploaded data?')) {
      try {
        setLoading(true);
        await axios.delete('http://localhost:5000/api/orders/latest');
        setOrders([]);
        setAlerts([]);
      } catch (error) {
        console.error('Error deleting latest orders:', error);
        alert('Error deleting data');
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-50/70 text-slate-800 p-4 sm:p-6 lg:p-8 font-sans">
      {/* Header Bar */}
      <header className="mb-6 bg-white rounded-2xl p-5 border border-slate-200/80 shadow-xs flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex-shrink-0 p-2 bg-slate-50 rounded-xl border border-slate-100">
            <img src="/Logo.png" alt="Logo" className="h-12 w-auto object-contain" />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Fleet Control Dashboard</h1>
            <p className="text-xs font-medium text-slate-500 mt-0.5">Truck Capacity & Logistics Optimization System</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {orders.length > 0 && (
            <button 
              onClick={handleDeleteLatest}
              className="flex items-center gap-2 px-3.5 py-2 bg-red-50 text-red-600 hover:bg-red-100 rounded-xl transition-all font-semibold text-xs border border-red-200/70 shadow-xs"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Clear Today's Data
            </button>
          )}
        </div>
      </header>

      {/* KPI Section */}
      <div className="mb-6">
        <KPIHeader orders={orders} />
      </div>

      {/* Upload Controls Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <FileUpload onUploadSuccess={handleUploadSuccess} />
        <ProductUpload />
      </div>

      {alerts.length > 0 && (
        <div className="mb-6">
          <ConsolidationAlerts alerts={alerts} />
        </div>
      )}

      {/* Main Table and Analytics Grid */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        <div className="xl:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200/80 p-5 overflow-hidden">
          <div className="flex items-center justify-between mb-4 border-b pb-3">
            <div>
              <h2 className="text-lg font-bold text-slate-800">Branch Details & Truck Allocations</h2>
              <p className="text-xs text-slate-400 mt-0.5">Click any row chevron to expand item breakdown</p>
            </div>
          </div>
          {loading ? (
            <div className="flex justify-center p-12">
              <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div>
            </div>
          ) : (
            <OrdersTable orders={orders} onUpdateActual={handleUpdateActualTrucks} />
          )}
        </div>
        <div className="xl:col-span-1">
          <AnalyticsChart orders={orders} />
        </div>
      </div>
    </div>
  );
}

export default App;
